import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import postcss from "postcss";
import selectorParser from "postcss-selector-parser";

const root = new URL("../", import.meta.url);
const frameworks = [
  {
    name: "bootstrap",
    source: "bootstrap/dist/css/bootstrap.min.css",
    license: "bootstrap/LICENSE",
    classes: {
      btn: "button",
      "btn-primary": "button--primary",
      "btn-secondary": "button--secondary",
      "btn-danger": "button--danger",
      "btn-link": "button--ghost",
      "form-control": "input",
      "card-header": "card__header",
      "card-body": "card__body",
      "card-footer": "card__footer",
      "alert-info": "alert--info",
      "alert-success": "alert--success",
      "alert-warning": "alert--warning",
      "alert-danger": "alert--danger"
    }
  },
  {
    name: "bulma",
    source: "bulma/css/bulma.min.css",
    license: "bulma/LICENSE",
    classes: {
      notification: "alert",
      tag: "badge",
      "card-header": "card__header",
      "card-content": "card__body",
      "card-footer": "card__footer"
    }
  },
  {
    name: "pico",
    source: "@picocss/pico/css/pico.min.css",
    license: "@picocss/pico/LICENSE.md",
    classes: {}
  }
];

const darkAttribute = /\[data-theme=(["']?)dark\1\]/g;

// System mode: repeat every dark rule for data-theme="system" inside a
// prefers-color-scheme query. The doubled attribute outranks vendor light
// rules such as :root:not([data-theme=dark]).
function addSystemDarkRule(rule) {
  if (rule.parent?.type === "atrule" && /keyframes$/.test(rule.parent.name)) return;
  const selectors = rule.selectors
    .filter(selector => /\[data-theme=(["']?)dark\1\]/.test(selector) && !/:not\([^)]*data-theme=(["']?)dark/.test(selector))
    .map(selector => selector.replace(darkAttribute, '[data-theme="system"][data-theme="system"]'));
  if (!selectors.length) return;
  const media = postcss.atRule({ name: "media", params: "(prefers-color-scheme: dark)" });
  media.append(rule.clone({ selectors }));
  rule.after(media);
}

// Default design system: copy only Open Props tokens that default CSS
// references (transitively). First file wins on duplicate names, so tinted
// oklch grays replace the hex grays from props.colors.css.
const openPropsFiles = [
  "props.gray-oklch.css",
  "props.colors.css",
  "props.sizes.css",
  "props.fonts.css",
  "props.borders.css",
  "props.shadows.css",
  "props.easing.css"
];
const openProps = new Map();
for (const file of openPropsFiles) {
  const css = postcss.parse(await readFile(new URL(`node_modules/open-props/src/${file}`, root), "utf8"));
  for (const node of css.nodes) {
    if (node.type !== "rule" || !/^:where\((html|\*)\)$/.test(node.selector)) continue;
    node.walkDecls(decl => {
      if (decl.prop.startsWith("--") && !openProps.has(decl.prop)) openProps.set(decl.prop, decl.value);
    });
  }
}
const referenced = text => [...text.matchAll(/var\(\s*(--[\w-]+)/g)].map(match => match[1]);
const pending = [];
for (const file of ["base.css", "default.css", "shared.css"]) {
  pending.push(...referenced(await readFile(new URL(`theme/default/${file}`, root), "utf8")));
}
const used = new Set();
while (pending.length) {
  const name = pending.pop();
  if (used.has(name) || !openProps.has(name)) continue;
  used.add(name);
  pending.push(...referenced(openProps.get(name)));
}
const openPropsVersion = JSON.parse(await readFile(new URL("node_modules/open-props/package.json", root), "utf8")).version;
const tokens = [...openProps].filter(([name]) => used.has(name)).map(([name, value]) => `\t${name}: ${value};`);
await writeFile(new URL("theme/default/open-props.css", root),
  `/* Generated by npm run build:themes from open-props@${openPropsVersion}.\n` +
  `   Subset: tokens referenced by base.css, default.css, shared.css.\n` +
  `   MIT License, see LICENSE-open-props.txt. */\n\n:where(html) {\n${tokens.join("\n")}\n}\n`);
await writeFile(new URL("theme/default/LICENSE-open-props.txt", root),
  await readFile(new URL("node_modules/open-props/LICENSE", root), "utf8"));
console.log(`Built open-props subset: ${tokens.length} tokens`);

const layout = postcss.parse(await readFile(new URL("theme/default/base.css", root), "utf8"));
layout.walkRules(rule => {
  if (!/\.(stack|grid|shell)\b/.test(rule.selector)) rule.remove();
});
layout.walkAtRules(rule => {
  if (!rule.nodes?.length) rule.remove();
});

for (const framework of frameworks) {
  const source = await readFile(new URL(`node_modules/${framework.source}`, root), "utf8");
  const css = postcss.parse(source, { from: framework.source });
  css.walkComments(comment => {
    if (comment.text.startsWith("# sourceMappingURL=")) comment.remove();
  });
  css.walkRules(rule => {
    // Preserve original framework selectors so custom components can use them too.
    const mapped = selectorParser(selectors => {
      selectors.walkClasses(node => {
        if (node.value === "form-select" && framework.name === "bootstrap") {
          node.replaceWith(selectorParser.tag({ value: "select" }), selectorParser.className({ value: "input" }));
          return;
        }
        if (node.value === "table" && framework.name !== "pico") {
          node.replaceWith(selectorParser.tag({ value: "table" }));
          return;
        }
        const replacement = framework.classes[node.value];
        if (replacement) node.value = replacement;
      });
      selectors.walkAttributes(node => {
        if (node.attribute === "data-bs-theme") node.attribute = "data-theme";
      });
    }).processSync(rule.selector);
    if (mapped !== rule.selector) rule.selector = `${rule.selector},${mapped}`;
    addSystemDarkRule(rule);
  });
  const adapter = await readFile(new URL(`theme/${framework.name}/adapter.css`, root), "utf8");
  const license = await readFile(new URL(`node_modules/${framework.license}`, root), "utf8");
  const banner = `/* Generated by npm run build:themes. See LICENSE.txt for upstream license. */\n`;
  const layoutReset = "\n.grid { grid-template-columns: none; grid-auto-columns: auto; }\n";
  await writeFile(new URL(`theme/${framework.name}/framework.css`, root),
    banner + css.toString() + "\n" + adapter + layoutReset + layout.toString());
  await writeFile(new URL(`theme/${framework.name}/LICENSE.txt`, root), license);
  console.log(`Built ${framework.name}: ${fileURLToPath(new URL(`theme/${framework.name}/framework.css`, root))}`);
}
